%% 02_separate_biological_abiotic_memory.m
% Reproducible PLSR analysis separating lagged water and biological memory
% associated with productivity legacy effects.
%
% REQUIRED INPUT:
%   legacy_results.mat generated by 01_quantify_legacy_effects.m
%
% CORE MODEL AT EACH PIXEL:
%   lambda(t) = beta2 * W(t-lag) + beta3 * P(t-lag) + e
%
% where:
%   lambda(t) = residual productivity after removing contemporaneous W effect
%   beta2     = water-memory coefficient
%   beta3     = biological-memory coefficient
%
% The main analysis uses lag = 1 year and the FULL interannual record.
% Sensitivity analyses:
%   (1) detectable legacy events only (sustained + reversed; Q10/Q90)
%   (2) lag lengths of 1, 2, and 3 years
%
% PLSR is used to reduce sensitivity to collinearity between lagged W and P.
% With two predictors, the script requests two PLS components when sample size
% permits. Coefficients are stored on the standardized scale because P and W
% were z-standardized in Script 01.

clear; clc;
rng(1,'twister');

%% ------------------------------------------------------------------------
% 1. USER SETTINGS
% -------------------------------------------------------------------------
input_file  = 'legacy_results.mat';
output_file = 'memory_plsr_results.mat';

lags = 1:3;
main_lag = 1;
min_samples_full = 10;
min_samples_detectable = 5;
ncomp_requested = 2;
main_q = 1; % Q10/Q90 in Script 01

%% ------------------------------------------------------------------------
% 2. LOAD INPUTS
% -------------------------------------------------------------------------
S = load(input_file, ...
    'P_z','W_z','legacy_raw','analysis_mask','event_class_all');

required = {'P_z','W_z','legacy_raw','analysis_mask','event_class_all'};
for k = 1:numel(required)
    if ~isfield(S,required{k})
        error('Missing required variable "%s" in %s.',required{k},input_file);
    end
end

P_z = double(S.P_z);
W_z = double(S.W_z);
lambda = double(S.legacy_raw);
analysis_mask = logical(S.analysis_mask);
event_class_all = double(S.event_class_all);

[rows,cols,nYears] = size(P_z);
if ~isequal(size(W_z),size(P_z)) || ~isequal(size(lambda),size(P_z))
    error('P_z, W_z, and legacy_raw must have identical dimensions.');
end

%% ------------------------------------------------------------------------
% 3. OUTPUT ARRAYS
% -------------------------------------------------------------------------
nLag = numel(lags);

beta_water_full = nan(rows,cols,nLag,'single');
beta_bio_full   = nan(rows,cols,nLag,'single');
R2_full         = nan(rows,cols,nLag,'single');
N_full          = zeros(rows,cols,nLag,'uint16');
VIP_water_full  = nan(rows,cols,nLag,'single');
VIP_bio_full    = nan(rows,cols,nLag,'single');

beta_water_detectable = nan(rows,cols,nLag,'single');
beta_bio_detectable   = nan(rows,cols,nLag,'single');
R2_detectable         = nan(rows,cols,nLag,'single');
N_detectable          = zeros(rows,cols,nLag,'uint16');
VIP_water_detectable  = nan(rows,cols,nLag,'single');
VIP_bio_detectable    = nan(rows,cols,nLag,'single');

%% ------------------------------------------------------------------------
% 4. FULL-RECORD PLSR AND DETECTABLE-EVENT SENSITIVITY
% -------------------------------------------------------------------------
fprintf('Running PLSR memory analysis ...\n');

for L = 1:nLag
    lag = lags(L);
    fprintf('  lag = %d year(s)\n',lag);

    for i = 1:rows
        if mod(i,20)==0 || i==1 || i==rows
            fprintf('    row %d / %d\n',i,rows);
        end
        for j = 1:cols
            if ~analysis_mask(i,j), continue; end

            p = squeeze(P_z(i,j,:));
            w = squeeze(W_z(i,j,:));
            y = squeeze(lambda(i,j,:));

            % -----------------------------------------------------------------
            % FULL INTERANNUAL RECORD
            % Response year t is paired with antecedent P/W at t-lag.
            % -----------------------------------------------------------------
            t_idx = (1+lag):nYears;
            Y = y(t_idx);
            X = [w(t_idx-lag), p(t_idx-lag)];
            valid = isfinite(Y) & all(isfinite(X),2);

            if sum(valid) >= min_samples_full
                [b,r2,vip] = local_plsr_coefficients(X(valid,:),Y(valid),ncomp_requested);
                beta_water_full(i,j,L) = single(b(1));
                beta_bio_full(i,j,L)   = single(b(2));
                R2_full(i,j,L)         = single(r2);
                VIP_water_full(i,j,L)  = single(vip(1));
                VIP_bio_full(i,j,L)    = single(vip(2));
                N_full(i,j,L)          = uint16(sum(valid));
            end

            % -----------------------------------------------------------------
            % DETECTABLE LEGACY EVENTS ONLY
            % event_class_all stores the extreme year t_event, whereas the
            % observed legacy response occurs in t_event+1. Therefore the
            % detectable response-year mask is shifted forward by one year.
            % For lag=1, predictors correspond to the extreme year itself.
            % -----------------------------------------------------------------
            cls_event = squeeze(event_class_all(i,j,:,main_q));
            detectable_response = false(nYears,1);
            ev = find(isfinite(cls_event) & cls_event~=0);
            ev = ev(ev+1 <= nYears);
            detectable_response(ev+1) = true;

            response_years = t_idx(:);
            keep_detectable = detectable_response(response_years);
            valid_det = valid & keep_detectable;

            if sum(valid_det) >= min_samples_detectable
                [b,r2,vip] = local_plsr_coefficients(X(valid_det,:),Y(valid_det),ncomp_requested);
                beta_water_detectable(i,j,L) = single(b(1));
                beta_bio_detectable(i,j,L)   = single(b(2));
                R2_detectable(i,j,L)         = single(r2);
                VIP_water_detectable(i,j,L)  = single(vip(1));
                VIP_bio_detectable(i,j,L)    = single(vip(2));
                N_detectable(i,j,L)          = uint16(sum(valid_det));
            end
        end
    end
end

%% ------------------------------------------------------------------------
% 5. MAIN MAPS (LAG = 1 YEAR)
% -------------------------------------------------------------------------
main_L = find(lags==main_lag,1);
if isempty(main_L)
    error('main_lag must be included in lags.');
end

water_memory_map      = beta_water_full(:,:,main_L);
biological_memory_map = beta_bio_full(:,:,main_L);

% Magnitudes can be used when the manuscript refers explicitly to memory
% "strength" independent of coefficient direction.
water_memory_strength      = abs(water_memory_map);
biological_memory_strength = abs(biological_memory_map);

%% ------------------------------------------------------------------------
% 6. SIMPLE CONSISTENCY SUMMARIES
% -------------------------------------------------------------------------
valid_both = isfinite(water_memory_map) & isfinite(biological_memory_map);
if any(valid_both(:))
    fprintf('\nMAIN 1-YEAR MEMORY SUMMARY\n');
    fprintf('  Valid pixels = %d\n',sum(valid_both(:)));
    fprintf('  Mean beta_water = %.4f\n',mean(water_memory_map(valid_both),'omitnan'));
    fprintf('  Mean beta_bio   = %.4f\n',mean(biological_memory_map(valid_both),'omitnan'));
    fprintf('  Mean |beta_water| = %.4f\n',mean(abs(water_memory_map(valid_both)),'omitnan'));
    fprintf('  Mean |beta_bio|   = %.4f\n',mean(abs(biological_memory_map(valid_both)),'omitnan'));
end

%% ------------------------------------------------------------------------
% 7. SAVE
% -------------------------------------------------------------------------
save(output_file, ...
    'beta_water_full','beta_bio_full','R2_full','N_full', ...
    'VIP_water_full','VIP_bio_full', ...
    'beta_water_detectable','beta_bio_detectable','R2_detectable','N_detectable', ...
    'VIP_water_detectable','VIP_bio_detectable', ...
    'water_memory_map','biological_memory_map', ...
    'water_memory_strength','biological_memory_strength', ...
    'lags','main_lag','main_q','min_samples_full','min_samples_detectable', ...
    '-v7.3');

fprintf('\nSaved: %s\n',output_file);

%% ========================================================================
% LOCAL FUNCTION: PLSR COEFFICIENTS, R2, VIP
% =========================================================================
function [b_pred,r2,vip] = local_plsr_coefficients(X,Y,ncomp_requested)
    X = double(X);
    Y = double(Y(:));

    % P and W were already standardized at each pixel in Script 01.
    % Do not rescale them again here, so beta2/beta3 retain the definition
    % used in the Methods. plsregress handles centering internally.
    sx = std(X,0,1,'omitnan');
    if any(~isfinite(sx) | sx==0)
        b_pred = [NaN NaN]; r2 = NaN; vip = [NaN NaN]; return;
    end

    maxcomp = min([ncomp_requested,size(X,2),size(X,1)-1]);
    if maxcomp < 1
        b_pred = [NaN NaN]; r2 = NaN; vip = [NaN NaN]; return;
    end

    [XL,~,XS,~,beta,PCTVAR,~,stats] = plsregress(X,Y,maxcomp);
    yhat = [ones(size(X,1),1) X] * beta;

    sse = sum((Y-yhat).^2,'omitnan');
    sst = sum((Y-mean(Y,'omitnan')).^2,'omitnan');
    if sst > 0
        r2 = 1-sse/sst;
    else
        r2 = NaN;
    end

    % beta(2:end) are coefficients for standardized W and P predictors.
    b_pred = beta(2:end)';

    % VIP calculation based on component-wise explained Y variance.
    p = size(X,2);
    W = stats.W;
    SSY = PCTVAR(2,1:maxcomp);
    vip = nan(1,p);
    denom = sum(SSY);
    if denom > 0
        for jj = 1:p
            contrib = 0;
            for a = 1:maxcomp
                wa = W(:,a);
                if sum(wa.^2)>0
                    contrib = contrib + SSY(a) * (W(jj,a)^2 / sum(wa.^2));
                end
            end
            vip(jj) = sqrt(p * contrib / denom);
        end
    end
end
